'use strict';

// These are structured retailer offers returned by the search provider, not
// numbers extracted from prose or prices generated by a language model.
function indexedOfferPrice(row, product, matchesIdentity) {
  const { classifyPriceSourceUrl } = require('./price-evidence');
  const { isGermanOfferPage } = require('./capture-web-price');
  const { captureOfferQuantityMatches } = require('./capture-offer-quantity');
  if (classifyPriceSourceUrl(row?.url).kind !== 'candidate' || !isGermanOfferPage(row.url)) return null;
  const text = `${row.title || ''} ${row.snippet || ''} ${row.source || ''} ${row.url}`;
  if (!captureOfferQuantityMatches(product, row.title)) return null;
  if (!matchesIdentity({ product, page: { text } })) return null;
  const sections = [row.richSnippet?.top, row.richSnippet?.bottom].filter(Boolean);
  for (const section of sections) {
    const extensions = (Array.isArray(section.extensions) ? section.extensions : []).filter(value => typeof value === 'string');
    if (!extensions.some(value => /^(auf lager|in stock|sofort lieferbar)$/i.test(value.trim()))) continue;
    if (extensions.some(value => /gebraucht|refurbished|out of stock|nicht lieferbar|zzgl.*mwst/i.test(value))) continue;
    // Some SerpAPI detected_extensions.price values lose the decimal comma
    // ("16,99 €" -> 1699). Read the explicit complete EUR price label instead.
    const prices = extensions.map(value => value.trim().match(/^(?:€|EUR)\s*(\d+(?:\.\d{3})*(?:,\d{2})?|\d+\.\d{2})$|^(\d+(?:\.\d{3})*(?:,\d{2})?|\d+\.\d{2})\s*(?:€|EUR)$/i))
      .filter(Boolean).map(match => {
        const value = match[1] || match[2];
        return Number(value.includes(',') ? value.replace(/\./g, '').replace(',', '.') : value);
      });
    if (prices.length === 1 && prices[0] >= 1 && prices[0] <= 20000) return prices[0];
  }
  return null;
}

module.exports = { indexedOfferPrice };
